import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type TimeblockCalendarProps = Record<string, any>;

const TimeblockCalendar: React.FC<TimeblockCalendarProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  dayName = "Today",
  timeBlocks = [
    {
      startTime: "10 AM",
      endTime: "2 PM",
      startHour24: 10,
      durationHours: 4,
      title: "Part-time job",
      color: "#FF9500",
    },
    {
      startTime: "2 PM",
      endTime: "5 PM",
      startHour24: 14,
      durationHours: 3,
      title: "Finalizing script",
      color: "#007AFF",
    },
    {
      startTime: "6 PM",
      endTime: "9 PM",
      startHour24: 18,
      durationHours: 3,
      title: "Photography gig",
      color: "#34C759",
    },
    {
      startTime: "9:30 PM",
      endTime: "11 PM",
      startHour24: 21.5,
      durationHours: 1.5,
      title: "Filming A-roll",
      color: "#AF52DE",
    },
  ],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const safeBlocks = timeBlocks.length > 0 ? timeBlocks : [{ startHour24: 9, durationHours: 8 }];
  const minHourRaw = Math.min(...safeBlocks.map((b) => b.startHour24));
  const maxHourRaw = Math.max(...safeBlocks.map((b) => b.startHour24 + b.durationHours));

  // Add padding to timeline
  const displayStart = Math.max(0, Math.floor(minHourRaw) - 1);
  const displayEnd = Math.min(24, Math.ceil(maxHourRaw) + 1);
  const totalDisplayHours = displayEnd - displayStart;

  const topOffset = height * 0.18;
  const bottomOffset = height * 0.1;
  const availableHeight = height - topOffset - bottomOffset;
  const hourHeight = availableHeight / totalDisplayHours;
  const timelineLeftOffset = width * 0.22;

  // Animations
  const titleProgress = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const timelineProgress = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14 },
  });

  const formatHour = (h: number) => {
    if (h === 0 || h === 24) return "12 AM";
    if (h === 12) return "12 PM";
    return h > 12 ? `${h - 12} PM` : `${h} AM`;
  };

  const hoursArray = Array.from({ length: totalDisplayHours + 1 }, (_, i) => displayStart + i);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      
      {/* Header / Day Name */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: timelineLeftOffset,
          opacity: titleProgress,
          transform: `translateY(${interpolate(titleProgress, [0, 1], [20, 0])}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: 64,
            fontWeight: 700,
            color: "#FFFFFF",
            letterSpacing: "-0.02em",
          }}
        >
          {dayName}
        </h1>
      </div>

      {/* Timeline Axis & Labels */}
      <div style={{ opacity: timelineProgress, transition: "none" }}>
        {hoursArray.map((hour) => {
          const yPos = topOffset + (hour - displayStart) * hourHeight;
          return (
            <React.Fragment key={`hour-${hour}`}>
              {/* Hour Label */}
              <div
                style={{
                  position: "absolute",
                  top: yPos - 14, // Center text vertically on the line
                  left: 0,
                  width: timelineLeftOffset - 20,
                  textAlign: "right",
                  color: "#8E8E93",
                  fontSize: 24,
                  fontWeight: 600,
                  transition: "none",
                }}
              >
                {formatHour(hour)}
              </div>
              
              {/* Horizontal Line */}
              <div
                style={{
                  position: "absolute",
                  top: yPos,
                  left: timelineLeftOffset,
                  width: width - timelineLeftOffset - (width * 0.05),
                  height: 1,
                  backgroundColor: "rgba(255, 255, 255, 0.1)",
                  transition: "none",
                }}
              />
            </React.Fragment>
          );
        })}
      </div>

      {/* Time Blocks */}
      {timeBlocks.map((block, index) => {
        const blockTop = topOffset + (block.startHour24 - displayStart) * hourHeight;
        const blockHeight = block.durationHours * hourHeight;
        
        const blockProgress = spring({
          frame: frame - (30 + index * 8),
          fps,
          config: { damping: 16, stiffness: 120 },
        });

        const revealPercentage = 100 - blockProgress * 100;

        return (
          <div
            key={`block-${index}`}
            style={{
              position: "absolute",
              top: blockTop,
              left: timelineLeftOffset,
              width: width - timelineLeftOffset - (width * 0.05),
              height: blockHeight,
              clipPath: `inset(0% 0% ${revealPercentage}% 0%)`,
              display: "flex",
              flexDirection: "column",
              overflow: "hidden",
              transition: "none",
            }}
          >
            {/* Background Tint */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: block.color,
                opacity: 0.15,
                borderRadius: 12,
                transition: "none",
              }}
            />
            
            {/* Left Solid Border */}
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: 6,
                backgroundColor: block.color,
                borderRadius: "12px 0 0 12px",
                transition: "none",
              }}
            />
            
            {/* Content */}
            <div
              style={{
                position: "relative",
                zIndex: 1,
                padding: "20px 24px",
                display: "flex",
                flexDirection: "column",
                gap: 8,
                transition: "none",
              }}
            >
              <span
                style={{
                  color: "#FFFFFF",
                  fontSize: 32,
                  fontWeight: 700,
                  lineHeight: 1.1,
                  transition: "none",
                }}
              >
                {block.title}
              </span>
              <span
                style={{
                  color: "rgba(235, 235, 245, 0.6)",
                  fontSize: 24,
                  fontWeight: 600,
                  transition: "none",
                }}
              >
                {block.startTime} - {block.endTime}
              </span>
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default TimeblockCalendar;